import React, { useState } from 'react';
import Signin from './Signin';

export default function App() {
  const [user, setUser] = useState(null);
  const [authKey, setAuthKey] = useState(Date.now()); // Used to force-reset the form on Sign Out

  const handleLoginSuccess = (userData) => {
    setUser(userData);
  };

  const handleSignOut = () => {
    // 1. Clear local storage token
    localStorage.removeItem('token');

    // 2. Clear current user state
    setUser(null);

    // 3. Update authKey to completely re-render Signin component blank
    setAuthKey(Date.now());
  };

  if (!user) {
    return <Signin key={authKey} onLoginSuccess={handleLoginSuccess} />;
  }

  return (
    <div style={{ padding: '40px', fontFamily: 'sans-serif' }}>
      <h1>Welcome, {user.name}!</h1>
      <p>Role: {user.role}</p>
      
      {/* Sign Out Button */}
      <button 
        onClick={handleSignOut}
        style={{
          padding: '10px 20px',
          backgroundColor: '#ef4444',
          color: '#fff',
          border: 'none',
          borderRadius: '8px',
          cursor: 'pointer',
          fontWeight: 'bold'
        }}
      >
        Sign Out
      </button>
    </div>
  );
}
